size: {
      '...size': (size = '$4') => {
        const sizeVal = +getTokenValue(size as any, 'size') / 3

        return {
          px: sizeVal,
          py: sizeVal * 1.5,
        }
      },
    }

functionalVariants.after:
size: styled.dynamic<SizeTokens>((size = '$4') => {
        const sizeVal = +getTokenValue(size as any, 'size') / 3

        return {
          px: sizeVal,
          py: sizeVal * 1.5,
        }
      })

